package com.mamtrex.hospital.radiology;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="radiology_orders") public class RadiologyOrder extends BaseEntity { private String patientId; private String modality; private String bodyRegion; private String report; private String status; protected RadiologyOrder(){} public RadiologyOrder(String patientId, String modality, String bodyRegion, String report, String status){this.patientId=patientId; this.modality=modality; this.bodyRegion=bodyRegion; this.report=report; this.status=status;} public String getPatientId(){return patientId;} public String getModality(){return modality;} public String getBodyRegion(){return bodyRegion;} public String getReport(){return report;} public String getStatus(){return status;} }
